    /// --canned-acl=PREDEFINED_ACL, --predefined-acl=PREDEFINED_ACL, -a PREDEFINED_ACL Applies predefined, or "canned," ACLs to a resource. See docs for a list of predefined ACL constants: https://cloud.google.com/storage/docs/access-control/lists#predefined-acl At most one of these can be specified: Cloud Storage allows you to configure a bucket to behave like a static website. A subsequent GET bucket request through a custom domain for a non-existent object serves the specified error page instead of the standard Cloud Storage error.
    /// </summary>
    [CliOption("--web-error-page", Format = OptionFormat.EqualsSeparated)]
    public string? WebErrorPage { get; set; }

    /// <summary>
    /// --canned-acl=PREDEFINED_ACL, --predefined-acl=PREDEFINED_ACL, -a PREDEFINED_ACL Applies predefined, or "canned," ACLs to a resource. See docs for a list of predefined ACL constants: https://cloud.google.com/storage/docs/access-control/lists#predefined-acl At most one of these can be specified: Clear website main page suffix if bucket is hosting website.
    /// </summary>
    [CliFlag("--clear-web-main-page-suffix")]
    public bool? ClearWebMainPageSuffix { get; set; }

    /// <summary>
    /// --canned-acl=PREDEFINED_ACL, --predefined-acl=PREDEFINED_ACL, -a PREDEFINED_ACL Applies predefined, or "canned," ACLs to a resource. See docs for a list of predefined ACL constants: https://cloud.google.com/storage/docs/access-control/lists#predefined-acl At most one of these can be specified: Cloud Storage allows you to configure a bucket to behave like a static website. A subsequent GET bucket request through a custom domain serves the specified "main" page instead of performing the usual bucket listing.
    /// </summary>
    [CliOption("--web-main-page-suffix", Format = OptionFormat.EqualsSeparated)]
    public string? WebMainPageSuffix { get; set; }

    [Obsolete("CannedAcl is no longer supported by the installed CLI and has no effect.")]
    public string? CannedAcl { get; set; }

